import{_ as a,H as t,f as i,i as n}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"07 | RAG生成：大模型与Prompt提示工程","description":"","frontmatter":{},"headers":[{"level":2,"title":"大模型发展","slug":"大模型发展","link":"#大模型发展","children":[]},{"level":2,"title":"大模型原理","slug":"大模型原理","link":"#大模型原理","children":[]},{"level":2,"title":"RAG 中如何选择大模型？","slug":"rag-中如何选择大模型","link":"#rag-中如何选择大模型","children":[]},{"level":2,"title":"提示工程","slug":"提示工程","link":"#提示工程","children":[]},{"level":2,"title":"RAG 中提示工程的技巧","slug":"rag-中提示工程的技巧","link":"#rag-中提示工程的技巧","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"RAG快速开发实战/07｜RAG生成：大模型与Prompt提示工程.md","filePath":"RAG快速开发实战/07｜RAG生成：大模型与Prompt提示工程.md","lastUpdated":1795533570000}'),s={name:"RAG快速开发实战/07｜RAG生成：大模型与Prompt提示工程.md"};function l(p,e,r,o,h,c){return t(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="_07-rag生成-大模型与prompt提示工程" tabindex="-1">07 | RAG生成：大模型与Prompt提示工程 <a class="header-anchor" href="#_07-rag生成-大模型与prompt提示工程" aria-label="Permalink to &quot;07 | RAG生成：大模型与Prompt提示工程&quot;">​</a></h1><ul><li>本门课程为精品小课，不标配音频。</li></ul><p>你好，我是常扬。</p><p>我们本节课正式开始讲解 RAG 生成流程。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/07/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/07/1.png" alt=""></a></p><p>如上图所示，经过 RAG 索引流程外部知识的解析及向量化，RAG 检索流程语义相似性的匹配及混合检索，系统进入 RAG 生成流程。生成流程中，首先需要组合指令，指令将携带查询问题及检索到的相关信息输入到大模型中，由大模型理解并生成最终的回复，从而完成整个应用过程。</p><p>RAG 的本质是通过为大模型提供外部知识来增强其理解和回答领域问题的能力，类似于为大语言模型配备插件，使其能够结合外部知识作出更为精准和符合上下文的回答。大模型在RAG 系统中起到大脑中枢的作用，尤其在面对复杂且多样化的 RAG 任务时，大模型的性能直接决定了整个系统的效果和响应质量，可以说大模型是整个系统的大脑。</p><p>提示词工程是生成流程中的另一关键环节。通过有效的指令的设计和组合，可以帮助大模型更好地理解输入内容，从而生成更加精确和相关的回答。精心设计的问题提示词往往能显著提升生成效果，反之则可能导致结果偏差。</p><p>这节课我们将深入探讨大模型的选择与提示词工程，提升 RAG 系统的生成效果。</p><h2 id="大模型发展" tabindex="-1">大模型发展 <a class="header-anchor" href="#大模型发展" aria-label="Permalink to &quot;大模型发展&quot;">​</a></h2><p>自 2022 年 OpenAI 公司发布 ChatGPT 以来，AI 2.0 时代 “Scaling Law” 大模型技术范式在全球范围内引发了人工智能学术与产业热潮。</p><p>根据中文大模型综合性测评基准 SuperCLUE 组织发布的 2024 年 8 月报告阐述，AI 大模型2023-2024 年关键进展大致可以分为四个阶段。</p><ol><li><p>准备期：ChatGPT 发布后国内产学研迅速形成大模型共识</p></li><li><p>成长期：国内大模型数量和质量开始逐渐增长</p></li><li><p>爆发期：各行各业开源闭源大模型层出不穷，形成百模大战的竞争态势</p></li><li><p>繁荣期：更多模态能力的延伸和应用</p></li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/07/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/07/2.png" alt=""></a></p><p>在 OpenAI 公司领衔的 GPT 系列及 Sora 的推动下，全球 AI 大模型技术进入了快速发展的新阶段。国内各大模型同步迅速跟进，市场从活跃到爆发，企业纷纷加大研发投入，推动了大模型技术从学术研究走向实际应用。在不到两年的时间里，新技术和新产品的迅速涌现，带来了行业的深度变革，标志着 AI 2.0 时代的加速到来。</p><p>同时 SuperCLUE 组织也发布了中文大模型全景图，展示了 2024 年值得关注的中文大模型，从通用、多模态、行业三个层面进行了详细分类，各领域的大模型应用层出不穷。RAG 中目前更关注通用大模型，比如闭源的文心一言、通义千问、腾讯混元、字节豆包、Kimi Chat 等都是可选择的大模型组件，如果需要私有化部署，Qwen 系列、GLM 系列、Baichuan 系列都在可考虑范围。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/07/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/07/3.png" alt=""></a></p><p>更多包含机构和学术背景且具有明确来源的大模型信息，可以访问实时更新的中国大模型列表，全面记录中国大模型的发展动态。</p><h2 id="大模型原理" tabindex="-1">大模型原理 <a class="header-anchor" href="#大模型原理" aria-label="Permalink to &quot;大模型原理&quot;">​</a></h2><p>一切始于 Google 在 2017 年发表的论文 《Attention Is All You Need》，引入了Transformer 模型，它是深度学习领域的一个突破性架构，大型语言模型的成功得益于对Transformer 模型的应用。</p><p>与传统的循环神经网络（RNN）相比，Transformer 模型不依赖于序列顺序，而是通过自注意力（Self-Attention）机制来捕捉序列中各元素之间的关系。Transformer 由多个堆叠的编码层（Encoder）和解码层（Decoder）组成，每一层包括自注意力层、前馈层和归一化层。这些层协同工作，逐步捕捉输入数据信息特征，从而预测输出，实现强大的语言理解和生成能力。</p><p>Transformer 模型的核心创新在于位置编码和自注意力机制。位置编码帮助模型理解输入数据的顺序信息，而自注意力机制则允许模型根据输入的全局上下文，为每个词元分配不同的注意力权重，从而更准确地理解词与词之间的关联性。这种机制使得 Transformer 特别适用于语言模型，因为语言模型需要精确捕捉上下文中的细微差别，生成符合语义逻辑的文本。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/07/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/07/4.png" alt=""></a></p><p>上图展示了 Transformer 模型的架构及其核心机制的可视化示例。左图中，Transformer 模型由编码器和解码器两部分组成。编码器负责理解输入信息的顺序和语义，解码器则输出概率最高的词元。</p><p>右上图中的示例显示了输入句子中的填空任务，解码器依据输入句子的特征和已生成的部分句子，生成了“She”作为模型的预测结果。生成“She”的核心原因在于右下图所示的注意力机制，其中需要填空的部分对输入句子中的词元“The Doctor”和“Nurse”分配了较高的注意力权重，从而提高了“She”作为输出词元的生成概率。</p><p>大语言模型的突破始于 2022 年年底 OpenAI 发布的 ChatGPT。其核心优势体现在庞大的参数规模（数百亿甚至数千亿）、基于 PB 级别数据的训练所带来的卓越语言理解与生成能力，以及其显著的涌现能力。大语言模型不仅在传统的自然语言处理任务中展现了卓越表现，还具备了解决复杂问题和进行逻辑推理等高级认知能力。</p><p>基于 Transformer 模型通过预测下一个词元的原理，大语言模型在分析了海量的语料库后，能够在逻辑上精准补全不完整的句子，甚至生成新的句子。这一推理模式赋予了大语言模型生成连贯且上下文相关文本的能力，使其在文本生成、翻译、问答系统等多个领域得到广泛应用。</p><h2 id="rag-中如何选择大模型" tabindex="-1">RAG 中如何选择大模型？ <a class="header-anchor" href="#rag-中如何选择大模型" aria-label="Permalink to &quot;RAG 中如何选择大模型？&quot;">​</a></h2><p>在如今大模型层出不穷的情况下，如何在 RAG 应用场景中选择合适的模型呢？我们面对的是开源与闭源的选择、大参数与小参数的对比，成本的考虑以及云端与私有化部署的抉择。针对这些问题，我们需要结合测评和具体的应用场景进行综合考量。</p><p>从测评角度来看，前面已经介绍了中文通用大模型的综合性测评基准 SuperCLUE，它对中文场景中的多个任务分支进行测试，涵盖基础能力、专业能力以及中文特性多个方面。每个任务分支又包含多个维度，例如语义理解、生成与创作、代数、生物、成语、诗词等。下图展示了这些维度的具体内容，SuperCLUE 每月都会更新测评结果，确保其反映大模型的最新表现。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/07/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/07/5.png" alt=""></a></p><ul><li>图片来自 <a href="https://www.cluebenchmarks.com/superclue_2408" target="_blank" rel="noreferrer">https://www.cluebenchmarks.com/superclue_2408</a></li></ul><p>尤其需要关注的是 SuperCLUE-RAG 检索增强生成测评，在 RAG 场景中，大模型的检索能力表现是核心。SuperCLUE 针对 RAG 应用场景进行了独立测试，具体评估了大模型在检索和生成过程中的表现，测试数据如下图所示（2024 年 9 月 5 日数据）。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/07/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/07/6.png" alt=""></a></p><p>在 SuperCLUE 官网的 SuperCLUE-RAG 检索增强生成分支页面上，可以查看其总榜及四大基础任务的测评结果。选择模型时可以根据总分，以及模型在答案及时性、信息整合能力、拒答能力、检错和纠错能力等方面的表现，进行综合评估，作为场景选型参考。</p><p>其次，也是最重要的，我们需要根据实际应用场景来考量并选择适合的大模型，以下几个维度是关键：</p><ol><li><p>开源与闭源：开源模型适用于数据敏感性高或有严格合规要求的场景，通过自托管实现对数据的完全掌控，确保隐私与安全。而闭源模型则适合数据敏感度较低的应用场景，其维护与服务相对完善，能够降低运维复杂度。</p></li><li><p>模型参数规模：大参数模型在复杂任务中的推理与生成能力较强，但并非所有应用场景都需要高精度模型。小参数模型（如 7B）在满足简单逻辑任务时，具备更优的响应速度、成本控制和资源利用效率。因此，模型规模应依据应用复杂性及算力预算进行合理匹配。</p></li><li><p>国内与国外部署：模型选择还需考虑部署环境。如果应用主要在国内进行，虽然调用国外大模型的接口是可行的，但可能会遇到稳定性、网络延迟、注册认证、充值付费等方面的实际问题。此外，数据合规性是重要考量，尤其对于需要遵循国内隐私和数据安全法规的场景，选择国内大模型或本地化部署更为合适。</p></li></ol><p>综上所述，模型的选择应结合 RAG 应用场景的需求和限制，更好地选择合适的大模型以最大化其效果。</p><p>最后对闭源和开源大模型做个分析和推荐。闭源与开源大模型在 RAG 应用中的选择需要结合参数规模、性能差异、成本及数据安全等多重因素加以考虑。</p><p>闭源大模型，如通义千问、文心一言、混元大模型、豆包大模型和 Kimi Chat 等，由于参数量较高，在 RAG 应用中的实际表现差异其实较小，此类大模型的选择更多地取决于成本需求。</p><p>开源大模型，基于其在国内的广泛使用和优异表现，推荐以下三个系列：</p><ol><li>Qwen 系列模型</li></ol><p>阿里云自研的 Qwen 系列（Qwen-1.8B、Qwen-7B、Qwen-14B、Qwen-72B 等）在包含 3万亿 token 的海量数据集上进行训练，数据源涵盖互联网文档、百科、书籍等，特别侧重于中英文双语的多语言数据。Qwen 系列在长上下文处理上表现出色，采用了 NTK 感知插值、窗口注意力等技术，将 Qwen-14B 的上下文长度从 2K 扩展至 8K 以上，Qwen-1.8B/7B 则从 8K扩展至 32K 个 Token。同时，LogN 注意力缩放技术进一步提升了模型在长上下文场景下的效率和表现，非常适合需要深度语义理解的 RAG 任务。</p><ol><li>Baichuan 系列模型</li></ol><p>百川发布的 Baichuan-7B 和 Baichuan-13B 模型，在接受了约 2.6 万个 Token 训练后，尤其在数学和编码任务中展现出卓越的性能。此外，百川系列模型在安全性方面经过了深入的评估，显示出比其他开源模型更强的安全性保障，这使其在需要高安全标准的 RAG 应用场景中更具吸引力。</p><ol start="2"><li>ChatGLM 系列模型</li></ol><p>由清华智谱研发的 ChatGLM 系列（包括 ChatGLM-6B、ChatGLM2-6B、ChatGLM3-6B 等）在中英双语数据集上训练，并对中文问答与对话任务进行了优化。ChatGLM 通过引入高效训练和长上下文处理技术，使得 ChatGLM2-6B-32K 模型能够处理多达 32K 个 Token 的上下文。这种能力对于 RAG 场景中的长文本检索和生成尤为关键。</p><h2 id="提示工程" tabindex="-1">提示工程 <a class="header-anchor" href="#提示工程" aria-label="Permalink to &quot;提示工程&quot;">​</a></h2><p>提示工程（Prompt Engineering）是为生成式 AI 模型设计输入以获取最佳输出的实践。这些输入被称为提示（Prompt），而编写这些提示的过程就是提示工程。其核心理念是，通过提供更优质的输入，可以让生成式 AI 模型（如大型语言模型）生成更符合需求的结果。这意味着模型能够更好地执行各种任务，包括问答、编写邮件、生成代码、分析和合成文本、与客户通过聊天机器人互动等。</p><p>提示工程是一门较新的技术，旨在通过开发和优化提示来有效利用语言模型的潜力。提示工程师的任务不仅仅是设计提示，而是通过深刻理解模型的功能和局限性，创造能够与模型输入产生最佳互动的提示。研究人员和开发人员通过提示工程来提升模型在执行常见和复杂任务（如问答、推理等）中的能力。提示工程不仅仅是设计和开发提示，而是包含了一系列的技能和技巧，这些技能和技巧有助于与语言模型的有效互动和功能扩展。</p><p>一个提示通常包含以下几类元素：</p><ol><li><p>指令（Instruction）：指明模型要执行的特定任务或操作。</p></li><li><p>上下文（Context）：为模型提供额外信息或背景，可以帮助引导模型生成更准确的响应。</p></li><li><p>输入数据（Input Data）：我们希望模型回答的问题或感兴趣的输入内容。</p></li><li><p>输出指示符（Output Indicator）：指定模型的输出类型或格式，例如格式、是否要求生成代码、总结文本或回答具体问题。</p></li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/07/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/07/7.png" alt=""></a></p><p>这些元素的组合和优化是提示工程的关键，能够直接影响大模型的性能和输出质量。</p><h2 id="rag-中提示工程的技巧" tabindex="-1">RAG 中提示工程的技巧 <a class="header-anchor" href="#rag-中提示工程的技巧" aria-label="Permalink to &quot;RAG 中提示工程的技巧&quot;">​</a></h2><p>在 RAG 场景中，提示工程不仅能够提升生成质量，还可以解决常见的 RAG 问题，如缺失内容、格式错误、缺乏细节和回答不全面等。以下是一些在 RAG 任务中常用的提示工程技巧。</p><ol><li>具体指令法</li></ol><p>通过向大模型提供具体、清晰的指令，能够提高输出的准确性。模糊的指示往往导致模型产生不理想的结果，而具体指令则有助于模型明确任务目标，生成更符合预期的内容。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请根据上传的银行业报告，简洁总结当前的市场趋势，重点分析政策变化对行业的影响，输出为以下Markdown</span></span>
<span class="line"><span>- **市场趋势**</span></span>
<span class="line"><span>- **政策影响**</span></span>
<span class="line"><span>- **竞争风险**</span></span></code></pre></div><ol start="2"><li>示例学习</li></ol><p>通过给模型提供多个参考示例，模型可以基于这些示例进行模式识别，进而模仿、思考并生成类似的答案。这种方法在无需对模型进行进一步训练的情况下，有效提升了模型的输出质量。</p><ul><li>以下是两个关于银行业的分析示例，请按照这种格式对新的报告进行分析：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- 示例 1：**市场趋势**：由于政策放宽，银行贷款增长迅速。</span></span>
<span class="line"><span>- 示例 2：**政策影响**：新的利率政策可能会对中小企业贷款产生负面影响。</span></span></code></pre></div><ul><li>请对下面报告进行同样的分析。</li></ul><ol start="3"><li>默认回复策略</li></ol><p>当模型无法从文档中获取足够信息时，通过设定默认回复策略，避免模型产生“幻觉”，即生成虚假的答案。这可以确保模型仅基于文档中的事实进行回答。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>如果文档中没有足够的事实回答问题，请返回{无法从文档中获得相关内容}，而不是进行推测。</span></span></code></pre></div><ol start="4"><li>任务角色设定</li></ol><p>通过为模型设定特定的角色身份，可以帮助模型更好地理解任务要求和角色责任，从而输出更加一致、专业的内容。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的角色: 知识库专家</span></span>
<span class="line"><span>- 背景：分析银行业市场数据</span></span>
<span class="line"><span>- 目标：生成一份详细的行业趋势分析</span></span>
<span class="line"><span>- 限制：仅根据报告中的数据生成分析</span></span></code></pre></div><ol start="5"><li>解释理由法</li></ol><p>在编写提示时，向模型解释为什么某些任务需要特定的处理方式。这样可以帮助模型更好地理解任务背景，从而提高输出的质量和相关性。</p><ul><li>请生成一份简明扼要的银行业报告摘要，不要逐字重复段落内容。原因：读者可以访问完整文档，如果需要可以</li></ul><ol start="6"><li>文档基础说明</li></ol><p>为模型提供文档的背景信息和文本来源可以帮助奠定任务基础，让模型更好地进行任务推理和回答。</p><ul><li>以下是关于银行业政策变化的相关规则，它们将用于回答有关政策对银行业影响的问题。</li></ul><p>通过这些提示工程技巧，RAG 任务的输出质量可以高效、低成本地提升，解决常见生成问题。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>这节课我们讲解了 RAG 生成流程中大模型与提示词工程。</p><ol><li>大模型与提示工程的作用</li></ol><p>大模型是 RAG 系统的核心大脑，承担中枢功能，处理输入信息并生成准确的回答。同时，提示工程通过设计有效且精确的提示词，可以显著提升 RAG 系统中大模型的生成效果。</p><ol start="2"><li>大模型</li></ol><p>自 ChatGPT 发布以来，大模型技术迅速发展，其演进过程可划分为准备期、成长期、爆发期和繁荣期。SuperCLUE 基准测评为中文大模型提供了月度更新的详尽性能评估数据，开发者可依据大模型在 RAG 检索场景的测评结果，并结合具体应用场景的需求，合理选择适用的大模型。</p><ol start="3"><li>提示工程</li></ol><p>提示工程通过为大模型设计高效且精确的提示词，能够有效引导大模型理解输入信息，从而提升生成的准确性与相关性。提示工程的核心在于设计任务指令、上下文信息、输入数据和输出格式的合理组合，通过具体指令、示例学习、默认回复策略、角色设定等技巧，有效解决生成过程中可能出现的缺失信息、格式错误等问题，提升 RAG 系统回答的生成效果。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>在提示工程中，过于具体的指令可能会限制模型的创造性，过于宽泛的提示则可能导致生成偏差。如何在提示设计中找到合适的权衡点，既能够引导模型生成高质量结果，又不过度限制模型的灵活性？请分享你在实际场景使用大模型提示工程中的经验。</p>`,87)])])}const E=a(s,[["render",l]]);export{g as __pageData,E as default};
